'use strict';

(function(){
  window.LABDS_LABS=window.LABDS_LABS||{};
  let root,ctx,state,worker,running=false,runStarted=0,runTimer=null;
  const defaults={code:`const tecnologias = ["HTML", "CSS", "JavaScript"];

for (const tecnologia of tecnologias) {
  console.log("Praticando:", tecnologia);
}

const nome = prompt("Digite seu nome:");
console.log("Olá, " + nome + "!");`,stdin:'Gabriel',logs:[]};
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function log(text,level='log'){state.logs.push({time:new Date().toLocaleTimeString('pt-BR'),text,level});state.logs=state.logs.slice(-250);renderConsole();}
  function renderConsole(){const el=root.querySelector('#jsConsole');if(el){el.innerHTML=state.logs.map(l=>`<div class="code-log ${l.level}"><span>${l.time}</span>${esc(l.text)}</div>`).join('')||'<div class="muted-copy">Execute o código para ver a saída.</div>';el.scrollTop=el.scrollHeight;}}
  function setRunning(value){running=value;root.querySelector('#jsRun').disabled=value;root.querySelector('#jsStop').disabled=!value;root.querySelector('#jsStatus').textContent=value?'executando':'pronto';root.querySelector('#jsStatus').dataset.tone=value?'busy':'success';}
  function run(){
    if(running)return;runStarted=performance.now();state.code=root.querySelector('#jsCode').value;if(state.code.length>100000){ctx.toast('O código excede o limite de 100 KB.','warning');return;}state.stdin=root.querySelector('#jsStdin').value;state.logs=[];renderConsole();worker=new Worker('js/workers/javascript-runner.js');setRunning(true);runTimer=setTimeout(()=>{if(running){log('Execução interrompida após 8 segundos.','warning');stop();}},8000);worker.onmessage=event=>{const {type,payload}=event.data||{};if(type==='console')log(payload.text,payload.level);else if(type==='error'){log(`${payload.name}: ${payload.message}`,'error');if(payload.stack)log(payload.stack.split('\n').slice(0,4).join('\n'),'dim');}else if(type==='done'){clearTimeout(runTimer);runTimer=null;setRunning(false);worker.terminate();worker=null;ctx.storage.set('lab.javascript.state',state);const stdin=/senha|password/i.test(state.code)?'[entrada omitida por possível campo de senha]':state.stdin;ctx.logEvent({eventType:'code_execution',action:'Código JavaScript executado',input:state.code,output:state.logs.map(l=>l.text).join('\n'),status:state.logs.some(l=>l.level==='error')?'error':'success',context:{language:'JavaScript',file:'main.js',stdin,durationMs:Math.round(performance.now()-runStarted),isolated:'Web Worker'}});}};worker.onerror=event=>{log(`Erro do Worker: ${event.message}`,'error');stop();};worker.postMessage({type:'run',code:state.code,stdin:state.stdin.split(/\r?\n/)});
  }
  function stop(){clearTimeout(runTimer);runTimer=null;if(worker){worker.terminate();worker=null;log('Execução interrompida pelo usuário.','warning');ctx?.logEvent({eventType:'code_execution',action:'Execução JavaScript interrompida',input:state.code,output:state.logs.map(l=>l.text).join('\n'),status:'interrupted',context:{language:'JavaScript',file:'main.js',durationMs:Math.round(performance.now()-runStarted)}});}setRunning(false);}
  async function mount(host,context){root=host;ctx=context;state={...defaults,...(await ctx.storage.get('lab.javascript.state',{}))};state.logs=[];root.innerHTML=`<div class="split-view code-lab"><section class="resizable-panel"><div class="panel-toolbar"><div class="tabs"><button class="tab-btn active" type="button">main.js</button></div><div class="button-row"><button id="jsRun" class="btn primary" type="button">Executar</button><button id="jsStop" class="btn secondary" type="button" disabled>Parar</button><button id="jsRestore" class="btn subtle" type="button">Restaurar exemplo</button></div></div><textarea id="jsCode" class="code-editor" spellcheck="false" aria-label="Código JavaScript"></textarea></section><section class="resizable-panel"><div class="panel-toolbar"><strong>Console isolado</strong><span id="jsStatus" data-tone="success">pronto</span></div><div class="stdin-box"><label>Entrada padrão — uma linha para cada <code>prompt()</code><textarea id="jsStdin" rows="4"></textarea></label></div><div id="jsConsole" class="console-card code-console"></div></section></div>`;root.querySelector('#jsCode').value=state.code;root.querySelector('#jsStdin').value=state.stdin;root.querySelector('#jsRun').addEventListener('click',run);root.querySelector('#jsStop').addEventListener('click',stop);root.querySelector('#jsRestore').addEventListener('click',()=>{if(confirm('Restaurar o exemplo inicial?')){root.querySelector('#jsCode').value=defaults.code;root.querySelector('#jsStdin').value=defaults.stdin;}});root.querySelector('#jsCode').addEventListener('keydown',event=>{if(event.key==='Tab'){event.preventDefault();const a=event.target,start=a.selectionStart,end=a.selectionEnd;a.value=a.value.slice(0,start)+'  '+a.value.slice(end);a.selectionStart=a.selectionEnd=start+2;}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();run();}});renderConsole();}
  function exportPayload(){const code=root?.querySelector('#jsCode')?.value||state.code;return{text:['AMBIENTE JAVASCRIPT',`Exportado em: ${new Date().toLocaleString('pt-BR')}`,'','===== CÓDIGO =====',code,'','===== CONSOLE =====',...state.logs.map(l=>`[${l.time}] ${l.text}`)].join('\n'),native:code,backup:{code,stdin:root?.querySelector('#jsStdin')?.value||state.stdin},meta:[{label:'Execução',value:'Web Worker isolado'}]};}
  function help(){return '<p>O JavaScript é executado em um Web Worker separado da interface. Use Ctrl+Enter para executar e Parar para encerrar loops longos.</p>';}
  async function unmount(){stop();if(ctx&&root){state.code=root.querySelector('#jsCode').value;state.stdin=root.querySelector('#jsStdin').value;await ctx.storage.set('lab.javascript.state',state);}root=null;ctx=null;}
  window.LABDS_LABS['javascript-lab']={mount,unmount,exportPayload,help};
})();
